t","required":true,"prompt_msg":"vaVars.previous_graph_node="Get User Active Badges___f1762558ad1c41c8992f1f3fa36e8afa";(function execute() {(function execute() {

 vaVars.user_badge_count = 0;
 var identityId = vaInputs.user_sys_id; 
 var badgeAction = "replace" //
 //TODO - DO not replace mobile creds
 var baseURL = gs.getProperty('glide.servlet.uri');
 var images = {};
 images['PERMANENT_BADGE'] = baseURL + '/x_aleen_aia_skills.permanentbadge.png';
 images['TEMP_BADGE'] = baseURL + '/x_aleen_aia_skills.visitorbadge.png';
 images['MOBILE_CREDENTIAL'] = baseURL + '/x_aleen_aia_skills.digitalbadge.png';

 var badgeArray = [];
 var badgeGr = new GlideRecordSecure('x_aleen_snguardian_identity_asset'); 
 badgeGr.addQuery('identity', identityId);
 badgeGr.addNotNullQuery('status');
 badgeGr.addQuery('status.code', 'ACTIVE');
 badgeGr.addQuery('is_deleted',false);
 badgeGr.addQuery('asset.type.code','!=','MOBILE_CREDENTIAL');
 badgeGr.query();
 while (badgeGr.next()) {
 badgeArray.push({
 'name': badgeGr.getDisplayValue("asset.serial")+"("+badgeGr.getDisplayValue("identifier") +")",
 'value':badgeGr.getValue("sys_id"),
 'description':badgeGr.getDisplayValue("identity.full_name") +" - " +badgeGr.getDisplayValue("valid_to")+" - " +badgeGr.getDisplayValue("status.name"),
 'body': images[badgeGr.getDisplayValue("asset.type.code")]
 });
 }
 vaVars.user_badges_list = JSON.stringify(badgeArray);
 if(badgeArray.length >0){
 vaVars.user_badge_count = badgeArray.length;
 }
})();})();vaInputs.__silent_ScriptedAction_f1762558ad1c41c8992f1f3fa36e8afa=true;null;","confirm_msg_on_default_value":{"msg":"","val_for_confirm":true},"nlu_text_input":false,"nlu_confirmation_prompt":false,"cardFields":[],"expert_mode":false,"acknowledge_msg":"vaVars.previous_graph_node="Get User Active Badges___f1762558ad1c41c8992f1f3fa36e8afa";var ackMsg=null;ackMsg=null;ackMsg;"},{"name":"__silent_Decision_57f7cf8c85964cf0a88fcfadeb5834e0","applicable":"(vaVars.previous_graph_node=="Get User Active Badges___f1762558ad1c41c8992f1f3fa36e8afa")","direction":"Input","required":true,"prompt_msg":"vaVars.previous_graph_node="Active Badges Found?___57f7cf8c85964cf0a88fcfadeb5834e0";vaInputs.__silent_Decision_57f7cf8c85964cf0a88fcfadeb5834e0=true;null;","confirm_msg_on_default_value":{"msg":"","val_for_confirm":true},"nlu_text_input":false,"nlu_confirmation_prompt":false,"cardFields":[],"expert_mode":false,"acknowledge_msg":"vaVars.previous_graph_node="Active Badges Found?___57f7cf8c85964cf0a88fcfadeb5834e0";var ackMsg=null;ackMsg=null;ackMsg;"},{"name":"__silent_Branch_58ebf43c7c0d4c6e9f7ae638df929a62","applicable":"(vaVars.previous_graph_node=="Active Badges Found?___57f7cf8c85964cf0a88fcfadeb5834e0") && ((function() { return (function execute() {
