 }else{
 vaVars.badge_valid_from_cal = "";
 }

 if("1970-01-01 00:00:00" != vaVars.dt_res_u_def_valid_to && "" != vaVars.dt_res_u_def_valid_to){
 vaVars.badge_valid_to_calc = new x_aleen_snguardian.TimeZoneUtil().getDurationDifference(vaVars.dt_res_u_def_valid_to, "add");
 }else{
 vaVars.badge_valid_to_calc = "";
 }

 //ASK USER INPUT :: IF MANUAL, valid from ==0 , valid to ==0
 if( vaVars.dt_res_u_create_request == "0"){
